def solve(n, edges, s, t):
    if s == t:
        return 0

    from collections import deque

    # Initialize distance array with infinity
    INF = float('inf')
    dist = [INF] * n
    dist[s] = 0

    # Use a deque for BFS-like approach with priority on shorter distances
    queue = deque()
    queue.append(s)

    while queue:
        u = queue.popleft()
        for v, w in edges:
            if u == v:
                continue
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                queue.append(v)

    return dist[t] if dist[t] != INF else -1

