    # Bellman-Ford algorithm to detect shortest path with possible negative weights
    # Since weights are between 0 and 100, we can use Dijkstra's for non-negative weights
    # But since there might be cycles, and to be safe, we use Bellman-Ford

    # Initialize distance array
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    # Check if t is reachable
    if dist[t] == float('inf'):
        return -1
    return dist[t]

