    for i in range(n - 1):
        for u in range(n):
            if dist[u] != float('inf'):
                for v, w in adj[u]:
                    if dist[v] > dist[u] + w:
                        dist[v] = dist[u] + w

    # Check if t is reachable
    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]

